// Pre-rendered Arial Bold watermark, 24 degrees, white 40% with a subtle dark stroke.
// Generated once; no font or external image request is needed at runtime.
export const watermarkStampPng = "";
export const watermarkStampFontSize = 46;

export const PHOTO_WATERMARK_VERSION = "levitate-preview-v2";
const preparationPrefix = new TextEncoder().encode("LEVITATE_PREVIEW\n");
const maximumBytes = 1024 * 1024;
const maximumEdge = 1600;
const maximumHeaderBytes = 64 * 1024;
const maximumMarkers = 65_536;

function invalid(message = "Prepara la foto desde administración antes de cargarla.", code = "portal_photo_preparation_required", statusCode = 400) {
  return Object.assign(new Error(message), { code, statusCode });
}

function checkDimensions(width, height) {
  if (!Number.isInteger(width) || !Number.isInteger(height) || width < 1 || height < 1) throw invalid();
  if (width > maximumEdge || height > maximumEdge || width * height > maximumEdge * maximumEdge) {
    throw invalid("Reduce la foto a un máximo de 1600 píxeles por lado antes de cargarla.", "portal_photo_too_large", 413);
  }
  return { width, height };
}

function preparationMetadata(payload) {
  if (payload.length > 512 || payload.length <= preparationPrefix.length
    || !preparationPrefix.every((value, index) => payload[index] === value)) throw invalid();
  let metadata;
  try { metadata = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(payload.subarray(preparationPrefix.length))); }
  catch { throw invalid(); }
  if (!metadata || Array.isArray(metadata) || typeof metadata !== "object"
    || Object.keys(metadata).sort().join(",") !== "height,sha256,version,width"
    || metadata.version !== PHOTO_WATERMARK_VERSION || typeof metadata.sha256 !== "string"
    || !/^[a-f0-9]{64}$/.test(metadata.sha256)) throw invalid();
  checkDimensions(metadata.width, metadata.height);
  return metadata;
}

// Validate JPEG structure and bounded headers without decoding image pixels.
// The marker catches wrong or changed files in the trusted admin workflow;
// it is deliberately not a cryptographic assertion about visible image text.
function inspectJpeg(bytes, requirePreparation) {
  if (!(bytes instanceof Uint8Array) || bytes.length < 4 || bytes[0] !== 0xff || bytes[1] !== 0xd8) throw invalid();
  if (bytes.length > maximumBytes) throw invalid("La vista previa debe pesar hasta 1 MB.", "portal_photo_too_large", 413);
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let position = 2;
  let frame;
  let prepared;
  let inScan = false;
  let hasScan = false;
  let markers = 0;
  while (position < bytes.length && ++markers <= maximumMarkers) {
    if (inScan) {
      position = bytes.indexOf(0xff, position);
      if (position < 0) throw invalid();
    }
    const markerStart = position;
    if (bytes[position++] !== 0xff) throw invalid();
    while (bytes[position] === 0xff && position < bytes.length) {
      if (++markers > maximumMarkers) throw invalid();
      position++;
    }
    if (position >= bytes.length) throw invalid();
    const marker = bytes[position++];
    if (inScan && marker === 0x00) continue;
    if (inScan && marker >= 0xd0 && marker <= 0xd7) continue;
    inScan = false;
    if (marker === 0xd9) {
      if (!frame || !hasScan || position !== bytes.length) throw invalid();
      if (requirePreparation && !prepared) throw invalid();
      return { ...frame, prepared };
    }
    if (marker === 0x00 || marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) throw invalid();
    if (position + 2 > bytes.length) throw invalid();
    const length = view.getUint16(position);
    const end = position + length;
    if (length < 2 || end > bytes.length || (!hasScan && end > maximumHeaderBytes)) throw invalid();
    if (marker === 0xe1 || marker === 0xfe) {
      throw invalid("Prepara la foto desde administración para retirar sus metadatos.", "portal_photo_metadata");
    }
    if (marker === 0xef) {
      if (!requirePreparation || prepared || markerStart !== 2) throw invalid();
      prepared = { ...preparationMetadata(bytes.subarray(position + 2, end)), start: markerStart, end };
    }
    if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker)) {
      if (![0xc0, 0xc1, 0xc2].includes(marker) || frame || hasScan || length < 11 || bytes[position + 2] !== 8) throw invalid();
      const components = bytes[position + 7];
      if (![1, 3].includes(components) || length !== 8 + 3 * components) throw invalid();
      frame = checkDimensions(view.getUint16(position + 5), view.getUint16(position + 3));
    }
    if (marker === 0xda) {
      if (!frame || length < 8 || length !== 6 + 2 * bytes[position + 2] || end >= bytes.length - 2) throw invalid();
      hasScan = true;
      inScan = true;
    }
    position = end;
  }
  throw invalid();
}

async function sha256(bytes) {
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest), value => value.toString(16).padStart(2, "0")).join("");
}

/** Add provenance after the caller has already burned the watermark. */
export async function addPreparedPhotoMarker(bytes, width, height) {
  const actual = inspectJpeg(bytes, false);
  if (actual.width !== width || actual.height !== height) throw invalid();
  const metadata = { version: PHOTO_WATERMARK_VERSION, width, height, sha256: await sha256(bytes) };
  const encoded = new TextEncoder().encode(JSON.stringify(metadata));
  const payload = new Uint8Array(preparationPrefix.length + encoded.length);
  payload.set(preparationPrefix);
  payload.set(encoded, preparationPrefix.length);
  const length = payload.length + 2;
  const result = new Uint8Array(bytes.length + payload.length + 4);
  if (result.length > maximumBytes) throw invalid("La vista previa debe pesar hasta 1 MB.", "portal_photo_too_large", 413);
  result.set(bytes.subarray(0, 2));
  result.set([0xff, 0xef, length >> 8, length & 0xff], 2);
  result.set(payload, 6);
  result.set(bytes.subarray(2), 6 + payload.length);
  return result;
}

/** Check preparation metadata and file integrity; does not inspect pixels. */
export async function validatePreparedParticipantPhoto(bytes) {
  const { width, height, prepared } = inspectJpeg(bytes, true);
  if (!prepared || prepared.width !== width || prepared.height !== height) throw invalid();
  const original = new Uint8Array(bytes.length - (prepared.end - prepared.start));
  original.set(bytes.subarray(0, prepared.start));
  original.set(bytes.subarray(prepared.end), prepared.start);
  if (await sha256(original) !== prepared.sha256) {
    throw invalid("La foto preparada cambió. Vuelve a prepararla desde administración.", "portal_photo_preparation_invalid");
  }
  return { bytes, width, height, contentType: "image/jpeg", watermarkVersion: PHOTO_WATERMARK_VERSION, sha256: await sha256(bytes) };
}
